import{_ as a,o as t,c as o,ag as s}from"./chunks/framework.CxkNbRKf.js";const n="/nada-documentation/images/mysql-workbench.png",i="/nada-documentation/images/mysql-workbench-export.png",b=JSON.parse('{"title":"Backup and Restore","description":"","frontmatter":{},"headers":[],"relativePath":"admin-guide/web-ui/backup.md","filePath":"admin-guide/web-ui/backup.md","lastUpdated":1786379412000}'),r={name:"admin-guide/web-ui/backup.md"};function p(l,e,d,c,u,h){return t(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="backup-and-restore" tabindex="-1">Backup and Restore <a class="header-anchor" href="#backup-and-restore" aria-label="Permalink to &quot;Backup and Restore&quot;">​</a></h1><h2 id="backup" tabindex="-1">Backup <a class="header-anchor" href="#backup" aria-label="Permalink to &quot;Backup&quot;">​</a></h2><p>To backup NADA, you need to backup the database and NADA application directory separately.</p><h3 id="backup-nada-database" tabindex="-1">Backup NADA Database <a class="header-anchor" href="#backup-nada-database" aria-label="Permalink to &quot;Backup NADA Database&quot;">​</a></h3><p>Depeding on your database type, follow the steps below to create a backup.</p><ul><li>Backup and restore MySQL database</li><li>Backup and restore Microsoft SQL Server database</li></ul><h3 id="backup-and-restore-mysql-database" tabindex="-1">Backup and restore MYSQL database <a class="header-anchor" href="#backup-and-restore-mysql-database" aria-label="Permalink to &quot;Backup and restore MYSQL database&quot;">​</a></h3><p>Depending on your hosting envoriment, you can backup and restore a MYSQL database using the following methods:</p><ul><li>Command line tools mysqldump and mysqlimport</li><li>MySQLWorkBench GUI</li><li>PHPMYADMIN</li></ul><h4 id="a-backup-and-restore-using-mysql-via-command-line" tabindex="-1">a) Backup and restore using MySQL via command line <a class="header-anchor" href="#a-backup-and-restore-using-mysql-via-command-line" aria-label="Permalink to &quot;a) Backup and restore using MySQL via command line&quot;">​</a></h4><p>MySQL provides a command line tool called MYSQLDUMP. This should be included with your installation of MYSQL.</p><p><strong>Steps to use MYSQLDUMP:</strong></p><p>i) Depending on your operating system, open the command line or shell terminal. For Windows, open the command window &quot;cmd.exe&quot; or &quot;Command Prompt&quot; from the start menu.</p><p>ii) Run the following command to backup the database:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mysqldump</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -u</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dbuser</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [db_name] </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [dumpfilename.sql]</span></span></code></pre></div><ul><li><strong>-u</strong> - is the user name for the database</li><li><strong>-p</strong> - enter the password or leave it empty to enter password in interactive mode</li><li><strong>[db_name]</strong> - put the nada database name</li><li><strong>[dumpfilename.sql]</strong> - enter the output file name</li></ul><p>Example: Exports the database <strong>nada4</strong> into a file <strong>nada4.sql</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>mysqldump -u root -p nada4 &gt; nada4.sql</span></span></code></pre></div><div class="tip custom-block"><p class="custom-block-title">Note</p><p>For more information about using the command, see: <a href="https://dev.mysql.com/doc/refman/5.6/en/mysqldump.html" target="_blank" rel="noreferrer">https://dev.mysql.com/doc/refman/5.6/en/mysqldump.html</a></p></div><p><strong>Steps to restore a database backup using MYSQLIMPORT</strong></p><p>i) From the command line, run the command:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>mysqlimport -u [user name] -p[password] [db_name] [db_backup.sql]</span></span></code></pre></div><ul><li><strong>-u</strong> - is the user name for the database</li><li><strong>-p</strong> - enter the password or leave it empty to enter password in interactive mode</li><li><strong>[db_name]</strong> - database name where the backup will be restored to</li><li><strong>[db_backup.sql]</strong> - enter the backup file name</li></ul><div class="tip custom-block"><p class="custom-block-title">Note::</p><p>For more information about using the tool, read: <a href="http://dev.mysql.com/doc/refman/5.6/en/mysqlimport.html" target="_blank" rel="noreferrer">http://dev.mysql.com/doc/refman/5.6/en/mysqlimport.html</a></p></div><h4 id="b-backup-database-using-mysqlworkbench" tabindex="-1">b) Backup database using MySQLWorkBench <a class="header-anchor" href="#b-backup-database-using-mysqlworkbench" aria-label="Permalink to &quot;b) Backup database using MySQLWorkBench&quot;">​</a></h4><p>MySQLWorkBench (<a href="https://www.mysql.com/products/workbench/" target="_blank" rel="noreferrer">https://www.mysql.com/products/workbench/</a>) is a free tool available for various operating systems and provides a visual tool for database administration. To download the software, visit: <a href="https://www.mysql.com/products/workbench/" target="_blank" rel="noreferrer">https://www.mysql.com/products/workbench/</a></p><p><strong>To backup using MySQLWorkBench, follow the steps:</strong></p><p>i) Launch the MySQL WorkBench application ii) On launching the application for first time, you will need to setup a &quot;New Server Instance&quot;. This is needed to setup a connection to the database to run queries and backup/restore databases.</p><p><img src="'+n+'" alt=""></p><p><strong>Steps to Create New Server Instance:</strong></p><p>i) Select New Server Instance option within Server Administrator. ii) Provide connection details such as the database server host name, user name, password to access the database. iii) Test the database connection and save it as new instance. iv) Double click on Server instance you have created OR Click on Manage Import/Export option and Select Server Instance. v) Under &quot;Server Administration&quot;, you have the options to import and export database. vi) To backup an existing database:</p><p><img src="'+i+'" alt=""></p><p>Select &quot;Data Export&quot; under DATA EXPORT/RESTORE. Select the database for export and then pick the option at the bottom &quot;Export to Self-Contained File&quot;, take note of the file path as this is where the backup file will be created. Now click on the &quot;Start Export&quot; button to export the database.</p><p><strong>Restore a database using MySQLWorkBench</strong></p><p>To restore the database, use the menu option &quot;Data Import/Restore&quot; under the DATA EXPORT/RESTORE. The steps to import are:</p><p>i) Click on the option &quot;Import from Self-Contained File&quot; and then provide the path to the backup file (.sql). ii) Default target Schema option: You can either leave it empty or fill in with the name of the database where you want the backup to be restored. If you provide a name of an existing database, the backup will overwrite the existing database.</p>',36)])])}const k=a(r,[["render",p]]);export{b as __pageData,k as default};
